import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './App.css';
import TSCFLogo from './tscf-logo.png';

function App() {
  const [formData, setFormData] = useState({
    surname: '', given_name: '', institution: '', dob: '', sex: '', marital_status: '',
    home_province: '', country: '', denomination: '', address: '', phone: '', mobile: '', email: '',
    college_university: '', member_role: '', year_of_graduation: '', field_of_study: '',
    graduate_program: '', fortnightly_amount: '', monthly_amount: '', yearly_amount: '',
    donation_amount: '', membership_type: '', membership_amount: '', membership_new_renewal: '',
    membership_number: ''
  });
  const [members, setMembers] = useState([]);
  const [showAdmin, setShowAdmin] = useState(false);

  useEffect(() => {
    fetchMembers();
  }, []);

  const fetchMembers = async () => {
    try {
      const response = await axios.get('/api/members');
      setMembers(response.data);
    } catch (err) {
      console.error(err);
    }
  };

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      await axios.post('/api/members', formData);
      alert('Application submitted successfully!');
      setFormData({
        surname: '', given_name: '', institution: '', dob: '', sex: '', marital_status: '',
        home_province: '', country: '', denomination: '', address: '', phone: '', mobile: '', email: '',
        college_university: '', member_role: '', year_of_graduation: '', field_of_study: '',
        graduate_program: '', fortnightly_amount: '', monthly_amount: '', yearly_amount: '',
        donation_amount: '', membership_type: '', membership_amount: '', membership_new_renewal: '',
        membership_number: ''
      });
      fetchMembers();
    } catch (err) {
      alert('Error submitting application. Email may already exist.');
      console.error(err);
    }
  };

  const updateStatus = async (id, status) => {
    try {
      await axios.put(`/api/members/${id}/status`, { application_status: status });
      fetchMembers();
    } catch (err) {
      console.error(err);
    }
  };

  const deleteMember = async (id) => {
    if (window.confirm('Are you sure?')) {
      try {
        await axios.delete(`/api/members/${id}`);
        fetchMembers();
      } catch (err) {
        console.error(err);
      }
    }
  };

  const graduatePrograms = [
    'Moore Bible College', 'Queensland Theological Seminary', 'Ministry Apprentice (MA)',
    'SAIACS -India', 'Corporate Training', 'Ministry Training Program', 'Seminars', 'Conferences', 'Empowerment Training'
  ];

  const membershipTypes = [
    { type: 'Student Member', amount: 20 },
    { type: 'Graduate Member', amount: 200 },
    { type: 'Life Member', amount: 2500 },
    { type: 'Partner', amount: 0 }
  ];

  return (
    <div className="App">
      <div className="header">
        <div className="logo-section">
          <img src={TSCFLogo} alt="TSCF Logo" className="logo" />
          <div>
            <h1>TERTIARY STUDENTS CHRISTIAN FELLOWSHIP</h1>
            <p className="address">National Membership: P. O. Box 6329 Port Boroko, National Capital District</p>
            <p className="mobile">Mobile: 73277901</p>
          </div>
        </div>
        <h2>TSCF VISION PARTNERS FORM 2026</h2>
        <p className="subtitle">The Voice of Truth: SALT & LIGHT</p>

        <div className="vision-section">
          <h3>Our Vision</h3>
          <p>To mobilize and facilitate the movement of graduates to impact the marketplace and the nation towards national salvation and transformation</p>

          <h3>Our Mission</h3>
          <p>By promoting a kingdom mindset through divine alignment, strategic alliance, partnership and fellowship amongst all graduates to become gatekeepers in our nation.</p>

          <h3>Core Values</h3>
          <p>Truth (God's Word), Servant Leadership, Integrity, Teamwork, Empowerment, Partnership and Advocacy</p>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="application-form">
        <h3>1. GENERAL INFORMATION</h3>
        <div className="form-grid">
          <div className="form-group"><label>Surname:</label><input name="surname" value={formData.surname} onChange={handleChange} required /></div>
          <div className="form-group"><label>Given Name:</label><input name="given_name" value={formData.given_name} onChange={handleChange} required /></div>
          <div className="form-group"><label>Institution:</label><input name="institution" value={formData.institution} onChange={handleChange} /></div>
          <div className="form-group"><label>DOB:</label><input type="date" name="dob" value={formData.dob} onChange={handleChange} /></div>
          <div className="form-group"><label>Sex:</label><select name="sex" value={formData.sex} onChange={handleChange}><option value="">Select</option><option value="Male">Male</option><option value="Female">Female</option></select></div>
          <div className="form-group"><label>Marital Status:</label><select name="marital_status" value={formData.marital_status} onChange={handleChange}><option value="">Select</option><option value="Married">Married</option><option value="Single">Single</option><option value="Divorced">Divorced</option><option value="Other">Other</option></select></div>
          <div className="form-group"><label>Home Province:</label><input name="home_province" value={formData.home_province} onChange={handleChange} /></div>
          <div className="form-group"><label>Country:</label><input name="country" value={formData.country} onChange={handleChange} /></div>
          <div className="form-group"><label>Denomination:</label><input name="denomination" value={formData.denomination} onChange={handleChange} /></div>
          <div className="form-group full-width"><label>Address:</label><textarea name="address" value={formData.address} onChange={handleChange} rows="2"></textarea></div>
          <div className="form-group"><label>Phone:</label><input name="phone" value={formData.phone} onChange={handleChange} /></div>
          <div className="form-group"><label>Mobile:</label><input name="mobile" value={formData.mobile} onChange={handleChange} /></div>
          <div className="form-group"><label>Email:</label><input type="email" name="email" value={formData.email} onChange={handleChange} required /></div>
        </div>

        <h3>2. EDUCATIONAL INFORMATION</h3>
        <div className="form-grid">
          <div className="form-group full-width"><label>College/University attended:</label><input name="college_university" value={formData.college_university} onChange={handleChange} /></div>
          <div className="form-group"><label>As a member:</label><input placeholder="Leader or Member" name="member_role" value={formData.member_role} onChange={handleChange} /></div>
          <div className="form-group"><label>Year of Graduation:</label><input type="number" name="year_of_graduation" value={formData.year_of_graduation} onChange={handleChange} /></div>
          <div className="form-group full-width"><label>Field of Study:</label><input name="field_of_study" value={formData.field_of_study} onChange={handleChange} /></div>
        </div>

        <h3>3. PARTNERS PROGRAMS</h3>
        <div className="form-group full-width">
          <label>Graduate Programs:</label>
          <select name="graduate_program" value={formData.graduate_program} onChange={handleChange}>
            <option value="">Select a program</option>
            {graduatePrograms.map(program => <option key={program}>{program}</option>)}
          </select>
        </div>

        <div className="donation-section">
          <h4>Donation Amounts (Kina)</h4>
          <div className="donation-row">
            <label>Fortnightly: K<input type="number" step="0.01" name="fortnightly_amount" value={formData.fortnightly_amount} onChange={handleChange} /></label>
            <label>Monthly: K<input type="number" step="0.01" name="monthly_amount" value={formData.monthly_amount} onChange={handleChange} /></label>
            <label>Yearly: K<input type="number" step="0.01" name="yearly_amount" value={formData.yearly_amount} onChange={handleChange} /></label>
            <label>Donation: K<input type="number" step="0.01" name="donation_amount" value={formData.donation_amount} onChange={handleChange} /></label>
          </div>
        </div>

        <div className="bank-details">
          <h4>TSCF Banking details</h4>
          <p>Tertiary Students Christian Fellowship</p>
          <p>1000435676 | Bank South Pacific | Boroko Banking Centre | BSB NO: 088-943</p>
          <p>SWIFT CODE: BOSPPGPM</p>
        </div>

        <h3>4. TYPE OF MEMBERSHIP</h3>
        <div className="membership-row">
          <label>New: <input type="radio" name="membership_new_renewal" value="New" onChange={handleChange} /></label>
          <label>Renewal: <input type="radio" name="membership_new_renewal" value="Renewal" onChange={handleChange} /></label>
          <label>Membership No: <input name="membership_number" value={formData.membership_number} onChange={handleChange} /></label>
        </div>
        <div className="membership-types">
          {membershipTypes.map(mt => (
            <label key={mt.type}>
              <input type="radio" name="membership_type" value={mt.type} onChange={handleChange} /> {mt.type} - K{mt.amount}
            </label>
          ))}
          <label>Custom Amount: K<input type="number" step="0.01" name="membership_amount" value={formData.membership_amount} onChange={handleChange} /></label>
        </div>

        <button type="submit" className="submit-btn">Submit Application</button>
      </form>

      <div className="admin-section">
        <button onClick={() => setShowAdmin(!showAdmin)} className="admin-toggle">
          {showAdmin ? 'Hide Admin Panel' : 'Show Admin Panel'}
        </button>
        {showAdmin && (
          <div className="admin-panel">
            <h3>Admin Dashboard - All Applications</h3>
            <div className="members-table">
              <table>
                <thead>
                  <tr><th>ID</th><th>Name</th><th>Email</th><th>Membership</th><th>Status</th><th>Actions</th></tr>
                </thead>
                <tbody>
                  {members.map(member => (
                    <tr key={member.id}>
                      <td>{member.id}</td><td>{member.surname}, {member.given_name}</td><td>{member.email}</td>
                      <td>{member.membership_type}</td><td>{member.application_status}</td>
                      <td>
                        <select onChange={(e) => updateStatus(member.id, e.target.value)} value={member.application_status}>
                          <option value="pending">Pending</option><option value="approved">Approved</option>
                          <option value="rejected">Rejected</option>
                        </select>
                        <button onClick={() => deleteMember(member.id)} className="delete-btn">Delete</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </div>

      <footer className="footer">
        <img src={TSCFLogo} alt="TSCF Logo" className="footer-logo" />
        <p>&copy; Tertiary Students Christian Fellowship 2026</p>
        <p className="footer-text">TSCF Vision Partners Application Form 2026</p>
      </footer>
    </div>
  );
}

export default App;
